const body = $input.first().json.body;
const required = ['target_keyword', 'content_type'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
const contentTypes = ['blog_post', 'landing_page', 'product_page', 'comparison_page', 'how_to_guide', 'listicle', 'pillar_page', 'case_study', 'faq_page'];
const contentType = contentTypes.includes(body.content_type) ? body.content_type : 'blog_post';
return [{ json: {
  valid: true,
  targetKeyword: body.target_keyword.trim(),
  contentType,
  businessDescription: (body.business_description || '').slice(0, 400),
  targetAudience: (body.target_audience || '').slice(0, 300),
  competitors: Array.isArray(body.competitors) ? body.competitors.slice(0, 5) : (body.competitors || '').split(',').map(c => c.trim()).filter(Boolean).slice(0, 5),
  relatedKeywords: Array.isArray(body.related_keywords) ? body.related_keywords : (body.related_keywords || '').split(',').map(k => k.trim()).filter(Boolean),
  contentGoal: body.content_goal || 'organic traffic',
  wordCountTarget: parseInt(body.word_count_target) || null,
  tone: body.tone || 'informative',
  existingContent: (body.existing_content_url || '').trim(),
  replyEmail: body.reply_email || null,
  requestedAt: new Date().toISOString()
} }];

const serpData = $('SERP Research').first().json?.results || [];
const paaData = $('PAA Research').first().json?.results || [];
const input = $('Validate Input').first().json;

const serpContext = serpData.map(r => `Title: ${r.title}\nURL: ${r.url}\nSnippet: ${(r.content||r.snippet||'').slice(0,300)}`).join('\n\n');
const paaContext = paaData.map(r => `${r.title}: ${(r.content||r.snippet||'').slice(0,200)}`).join('\n');

const competingTitles = serpData.map(r => r.title).filter(Boolean);
const domains = serpData.map(r => { try { return new URL(r.url).hostname; } catch(e) { return r.url; } });

return [{ json: { input, serpContext, paaContext, competingTitles, topDomains: domains.slice(0,6) } }];

values.content:
Create a detailed SEO content brief.

Target keyword: {{ $json.input.targetKeyword }}
Content type: {{ $json.input.contentType.replace(/_/g,' ') }}
Business: {{ $json.input.businessDescription || 'not specified' }}
Target audience: {{ $json.input.targetAudience || 'general' }}
Content goal: {{ $json.input.contentGoal }}
Word count target: {{ $json.input.wordCountTarget || 'not specified' }}
Tone: {{ $json.input.tone }}
Related keywords: {{ $json.input.relatedKeywords.join(', ') || 'none provided' }}
Competitors to beat: {{ $json.input.competitors.join(', ') || 'none specified' }}

Current SERP top results:
{{ $json.serpContext }}

People Also Ask context:
{{ $json.paaContext }}

Competing titles currently ranking:
{{ $json.competingTitles.join('\n') }}

Top domains ranking:
{{ $json.topDomains.join(', ') }}

Return this JSON:
{
  "brief_title": "internal title for this brief",
  "search_intent": {
    "type": "one of: informational | navigational | commercial | transactional",
    "description": "what the searcher is actually trying to accomplish — be specific",
    "stage": "one of: awareness | consideration | decision"
  },
  "recommended_title": "a specific, click-worthy title that matches intent and includes the keyword naturally",
  "title_alternatives": ["2 additional title options with different angles"],
  "target_word_count": 0,
  "meta_description": "compelling 150-160 character meta description",
  "primary_keyword": "{{ $json.input.targetKeyword }}",
  "secondary_keywords": ["6-10 semantically related terms to include naturally"],
  "content_angle": "the specific angle or hook that differentiates this piece from what's already ranking — be concrete",
  "content_gap": "what the top-ranking content is missing or doing poorly that this piece can exploit",
  "suggested_structure": [
    {
      "section": "H1 or H2 heading text",
      "type": "intro | h2 | h3 | faq | cta",
      "purpose": "what this section accomplishes for the reader and for SEO",
      "notes": "specific things to include, stats to find, or questions to answer",
      "approximate_words": 150
    }
  ],
  "must_include_topics": ["specific topics, statistics, or questions that must be addressed to be comprehensive"],
  "faq_questions": ["4-6 FAQ questions that match PAA queries for this keyword"],
  "internal_linking_suggestions": ["types of pages or content to link to from this piece"],
  "competitor_analysis": {
    "what_ranks": "what type of content is dominating the SERP and why",
    "weaknesses": "where current top results fall short",
    "differentiation_opportunity": "the specific opportunity for a new piece to outperform them"
  },
  "e_e_a_t_requirements": ["specific E-E-A-T signals this content needs: author bio, citations, case studies, etc."],
  "technical_seo_notes": ["canonical strategy, schema markup recommendations, featured snippet opportunity"]
}

parameters.jsCode:
const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let brief;
try { brief = JSON.parse(raw.replace(/```json|```/g,'').trim()); } catch(e) { return [{ json: { error: 'Parse error', raw } }]; }
const input = $('Validate Input').first().json;
brief._meta = { targetKeyword: input.targetKeyword, contentType: input.contentType, replyEmail: input.replyEmail };
return [{ json: brief }];

const b = $input.first().json;
const m = b._meta;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

const intentColors = {informational:'#2563eb', navigational:'#6b7280', commercial:'#d97706', transactional:'#16a34a'};
const intentColor = intentColors[b.search_intent?.type] || '#6b7280';
const stageColors = {awareness:'#6b7280', consideration:'#d97706', decision:'#16a34a'};
const stageColor = stageColors[b.search_intent?.stage] || '#6b7280';

const structureRows = (b.suggested_structure||[]).map((s,i) => {
  const typeColors = {intro:'#6b7280', h2:'#2563eb', h3:'#7c3aed', faq:'#0891b2', cta:'#16a34a'};
  const tc = typeColors[s.type]||'#6b7280';
  return `<div style="border-left:3px solid ${tc};padding:12px 16px;margin-bottom:10px;background:#fafafa;border-radius:0 6px 6px 0">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px">
      <span style="background:${tc}22;color:${tc};font-size:11px;font-weight:700;padding:2px 8px;border-radius:8px;text-transform:uppercase">${esc(s.type)}</span>
      <span style="font-size:12px;color:#9ca3af">~${s.approximate_words||'?'} words</span>
    </div>
    <div style="font-size:15px;font-weight:600;color:#1a1a1a;margin-bottom:4px">${esc(s.section)}</div>
    <div style="font-size:13px;color:#555;margin-bottom:4px">${esc(s.purpose)}</div>
    ${s.notes ? `<div style="font-size:12px;color:#2563eb;background:#eff6ff;padding:6px 10px;border-radius:4px">${esc(s.notes)}</div>` : ''}
  </div>`;
}).join('');

const kw2ary = (b.secondary_keywords||[]).map(k => `<span style="display:inline-block;background:#f3f4f6;color:#374151;font-size:12px;padding:3px 10px;border-radius:12px;margin:3px 3px 0 0">${esc(k)}</span>`).join('');
const faqItems = (b.faq_questions||[]).map((q,i) => `<div style="font-size:14px;padding:7px 0;border-bottom:1px solid #f3f4f6;color:#374151">${i+1}. ${esc(q)}</div>`).join('');
const mustInclude = (b.must_include_topics||[]).map(t => `<li style="font-size:14px;margin-bottom:6px;line-height:1.5">${esc(t)}</li>`).join('');
const eeat = (b.e_e_a_t_requirements||[]).map(e => `<div style="font-size:13px;padding:5px 0;border-bottom:1px solid #f0f9ff;color:#1e40af">✦ ${esc(e)}</div>`).join('');
const titleAlts = (b.title_alternatives||[]).map((t,i) => `<div style="font-size:14px;padding:7px 0;border-bottom:1px solid #f3f4f6;color:#374151">${i+2}. ${esc(t)}</div>`).join('');

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:16px;background:#f5f5f0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#111">
<div style="max-width:720px;margin:0 auto">
  <div style="background:#111827;color:#fff;padding:20px 28px;border-radius:10px 10px 0 0">
    <div style="font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#6b7280;margin-bottom:5px">SEO Content Brief · ${esc(m.contentType.replace(/_/g,' '))}</div>
    <div style="font-size:19px;font-weight:700">${esc(b.brief_title||m.targetKeyword)}</div>
    <div style="font-size:14px;color:#9ca3af;margin-top:4px">Primary keyword: <strong>${esc(m.targetKeyword)}</strong></div>
  </div>
  <div style="background:#fff;padding:16px 28px;border:1px solid #e5e7eb;border-top:none">
    <div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:12px">
      <span style="background:${intentColor}22;color:${intentColor};font-size:12px;font-weight:700;padding:4px 12px;border-radius:12px">${esc(b.search_intent?.type||'?')} intent</span>
      <span style="background:${stageColor}22;color:${stageColor};font-size:12px;font-weight:700;padding:4px 12px;border-radius:12px">${esc(b.search_intent?.stage||'?')} stage</span>
      ${b.target_word_count ? `<span style="background:#f3f4f6;color:#374151;font-size:12px;padding:4px 12px;border-radius:12px">${b.target_word_count} words</span>` : ''}
    </div>
    <p style="font-size:14px;color:#374151;line-height:1.65;margin:0">${esc(b.search_intent?.description)}</p>
  </div>
  <div style="background:#fff;padding:16px 28px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:8px">Recommended title</div>
    <div style="font-size:17px;font-weight:700;color:#1a1a1a;margin-bottom:8px">${esc(b.recommended_title)}</div>
    ${titleAlts}
    <div style="margin-top:10px;font-size:13px;color:#6b7280;background:#f9fafb;padding:8px 12px;border-radius:4px"><strong>Meta:</strong> ${esc(b.meta_description)}</div>
  </div>
  <div style="background:#eff6ff;padding:14px 28px;border:1px solid #bfdbfe">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#1d4ed8;margin-bottom:6px">Content angle & gap</div>
    <p style="font-size:14px;color:#1e40af;line-height:1.65;margin:0 0 8px"><strong>Angle:</strong> ${esc(b.content_angle)}</p>
    <p style="font-size:14px;color:#1e40af;line-height:1.65;margin:0"><strong>Gap:</strong> ${esc(b.content_gap)}</p>
  </div>
  <div style="background:#fff;padding:16px 28px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:8px">Secondary keywords</div>
    ${kw2ary}
  </div>
  <div style="background:#fff;padding:16px 28px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:10px">Content structure</div>
    ${structureRows}
  </div>
  ${mustInclude ? `<div style="background:#fff;padding:14px 28px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:8px">Must include</div>
    <ul style="padding-left:18px;margin:0">${mustInclude}</ul>
  </div>` : ''}
  ${faqItems ? `<div style="background:#fff;padding:14px 28px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:8px">FAQ questions to answer</div>
    ${faqItems}
  </div>` : ''}
  <div style="background:#fff;padding:14px 28px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:8px">Competitor analysis</div>
    <div style="font-size:14px;color:#374151;margin-bottom:6px"><strong>What ranks:</strong> ${esc(b.competitor_analysis?.what_ranks)}</div>
    <div style="font-size:14px;color:#374151;margin-bottom:6px"><strong>Weaknesses:</strong> ${esc(b.competitor_analysis?.weaknesses)}</div>
    <div style="font-size:14px;color:#16a34a"><strong>Opportunity:</strong> ${esc(b.competitor_analysis?.differentiation_opportunity)}</div>
  </div>
  ${eeat ? `<div style="background:#f0f9ff;padding:14px 28px;border:1px solid #bae6fd">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#0369a1;margin-bottom:7px">E-E-A-T requirements</div>
    ${eeat}
  </div>` : ''}
  <div style="background:#111827;color:#4b5563;font-size:11px;padding:12px 28px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">
    SEO Brief Generator · ${esc(m.targetKeyword)} · ${new Date().toLocaleDateString()}
  </div>
</div></body></html>`;

return [{ json: { html, replyEmail: m.replyEmail, targetKeyword: m.targetKeyword, recommendedTitle: b.recommended_title, brief: b } }];
